const COLUMNS = ['id', 'customer', 'total', 'placedAt'];

/** One CSV value: quoted when it holds a comma, a quote or a line break. */
const cell = (value) => {
  const text = String(value ?? '');
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};

/** The orders as CSV text: a header row, then one row per order. */
exports.toCsv = (orders) =>
  [COLUMNS, ...orders.map((o) => COLUMNS.map((c) => o[c]))].map((row) => row.map(cell).join(',')).join('\n') + '\n';
